/**
 * Utility to animate text in a character-by-character, ethereal 56k modem style
 */

// Function to add random delay to characters
const getRandomDelay = (min, max) => {
  return Math.random() * (max - min) + min;
};

// Function to determine if a character should get special effects
const shouldApplyEffect = probability => {
  return Math.random() < probability;
};

/**
 * Animates text content character by character with varying delays
 * @param {HTMLElement} element - The element containing text to animate
 * @param {Object} options - Animation options
 */
export const animateText = (element, options = {}) => {
  if (!element) return;
  const defaults = {
    minDelay: 0.02,
    // Minimum delay between characters (seconds)
    maxDelay: 0.15,
    // Maximum delay between characters (seconds)
    lineDelay: 0.3,
    // Additional delay for new lines
    flickerProbability: 0.08,
    // Probability of a character flickering
    glowProbability: 0.05,
    // Probability of a character glowing
    excludeSelectors: ['button', 'input', '.no-animate'] // REMOVED 'a' to allow link text to animate
  };
  const settings = {
    ...defaults,
    ...options
  };

  // Skip elements that should be excluded
  if (settings.excludeSelectors.some(selector => element.matches && element.matches(selector))) {
    return;
  }

  // Get original text content
  const originalText = element.textContent || '';
  if (originalText.trim() === '') return; // Skip empty text

  // Store original styles to preserve them
  const originalColor = window.getComputedStyle(element).color;
  const originalFontFamily = window.getComputedStyle(element).fontFamily;
  const originalFontSize = window.getComputedStyle(element).fontSize;
  const originalFontWeight = window.getComputedStyle(element).fontWeight;
  element.classList.add('text-animate-container');

  // Clear the element
  element.innerHTML = '';

  // Add each character with random delays
  let cumulativeDelay = 0;
  let isPreviousNewline = false;
  [...originalText].forEach(char => {
    // Check if character is a newline or space
    if (char === '\n') {
      isPreviousNewline = true;
      element.appendChild(document.createElement('br'));
      return;
    }
    const charSpan = document.createElement('span');

    // Use textContent for normal characters, preserves text better than innerHTML
    if (char === ' ') {
      // Special handling for spaces to ensure they're preserved
      charSpan.innerHTML = '&nbsp;';
    } else {
      // For all other characters, use textContent which is safer
      charSpan.textContent = char;
    }

    // Apply original text styles to ensure consistent rendering
    charSpan.style.color = originalColor;
    charSpan.style.fontFamily = originalFontFamily;
    charSpan.style.fontSize = originalFontSize;
    charSpan.style.fontWeight = originalFontWeight;
    charSpan.classList.add('text-animate-char');

    // Add special line delay if starting a new line
    if (isPreviousNewline) {
      cumulativeDelay += settings.lineDelay;
      isPreviousNewline = false;
    }

    // Get random delay for this character
    const thisDelay = getRandomDelay(settings.minDelay, settings.maxDelay);
    cumulativeDelay += thisDelay;

    // Apply the delay
    charSpan.style.animationDelay = `${cumulativeDelay}s`;

    // Add special effects to some characters
    if (shouldApplyEffect(settings.flickerProbability)) {
      charSpan.classList.add('text-animate-flicker');
    }
    if (shouldApplyEffect(settings.glowProbability)) {
      charSpan.classList.add('text-animate-glow');
    }
    element.appendChild(charSpan);
  });
  return cumulativeDelay; // Return total animation duration
};

/**
 * Process a container and animate all text nodes within it
 * @param {HTMLElement} container - Container element
 * @param {Object} options - Animation options
 */
export const animateTextInContainer = (container, options = {}) => {
  if (!container) return;

  // Get all text-containing elements to animate
  // This improved approach handles nested elements better
  const elementsToAnimate = [];

  // Define elements we want to skip entirely (never animate their children)
  const skipElements = options.skipElements || ['a.alien-title', '.count', '.sub-links', 'nav', 'button', 'input'];

  // Function to process an element and its children
  const processElement = element => {
    // Skip specified elements completely
    if (skipElements.some(selector => element.matches && element.matches(selector))) {
      return;
    }

    // If element has only text and no other elements, animate it directly
    if (element.childNodes.length === 1 && element.childNodes[0].nodeType === Node.TEXT_NODE) {
      const text = element.textContent.trim();
      if (text.length > 0) {
        elementsToAnimate.push(element);
      }
      return;
    }

    // Process child nodes
    Array.from(element.childNodes).forEach(child => {
      if (child.nodeType === Node.TEXT_NODE) {
        // Found a text node that needs to be wrapped
        if (child.textContent.trim().length > 0) {
          const wrapper = document.createElement('span');
          wrapper.textContent = child.textContent;
          wrapper.style.display = 'inline'; // Ensure proper inline display
          child.parentNode.replaceChild(wrapper, child);
          elementsToAnimate.push(wrapper);
        }
      } else if (child.nodeType === Node.ELEMENT_NODE) {
        // Process element node
        processElement(child);
      }
    });
  };

  // Start processing from the container
  processElement(container);

  // Animate each element
  elementsToAnimate.forEach(el => {
    animateText(el, options);
  });
};

