  // Animate the main content area
  const mainContent = document.querySelector('.main-content');
  if (mainContent) {
    animateTextInContainer(mainContent, {
      minDelay: 0.015,
      maxDelay: 0.12,
      skipElements: ['a.alien-title', '.sub-links', 'nav', 'button', 'input']
    });
  }

  // Specifically target category items
  const categoryItems = document.querySelectorAll('.category-item');
  categoryItems.forEach((item, index) => {
    setTimeout(() => {
      const links = item.querySelectorAll('a');
      links.forEach(link => {
        animateText(link, {
          minDelay: 0.01,
          maxDelay: 0.08
        });
      });

      // Animate the count separately
      const count = item.querySelector('.count');
      if (count) {
        setTimeout(() => {
          animateText(count, {
            minDelay: 0.005,
            maxDelay: 0.03
          });
        }, 100);
      }
    }, index * 50); // Stagger the animation of items
  });
};
